const sC=(v,n)=>v==null?"":String(v).slice(0,n);const RE_ISOC=/^\d{4}-\d{2}-\d{2}$/,RE_IDC=/^[\w|-]{1,130}$/,okT=t=>/^\d{4}-\d\d-\d\dT/.test(String(t||""));
