  const c=cursoAct();if(CUR.sub==="asis")bindAsis(c);else if(CUR.sub==="notas")bindNotas(c);else if(CUR.sub==="ses")bindSesiones(c);else if(CUR.sub==="cal")bindCalCur();else bindLista(c);
