const camposC=c=>(c&&c.campos)||[];const valCF=(i,cf)=>(i.extra&&i.extra[cf.id])||"";
function vLista(c){const CF=camposC(c);let L=insDe(c.id,CUR.verRet).filter(x=>!CUR.q||normK(nomEst(x.e)+" "+x.e.doc+" "+x.e.correo+" "+x.i.n+" "+x.e.plan+" "+Object.values(x.i.extra||{}).join(" ")).includes(normK(CUR.q)));const agr=CF.find(f=>f.id===CUR.agr);if(agr)L=L.slice().sort((a,b)=>(valCF(a.i,agr)||"\uffff").localeCompare(valCF(b.i,agr)||"\uffff","es",{numeric:true})||String(a.i.n).localeCompare(String(b.i.n)));const nr=C.ins.filter(i=>i.cur===c.id&&i.estado==="retirado").length;
  return`<div class="filters"><button class="b s p" id="lImp">📋 Importar / actualizar listado</button><button class="b s" id="lNuevo">+ Estudiante</button><input id="lQ" placeholder="Buscar…" value="${esc(CUR.q)}" style="flex:1;min-width:120px">${nr?`<label class="small" style="margin:0"><input type="checkbox" id="lRet" ${CUR.verRet?"checked":""}> ver ${nr} retirados</label>`:""}<button class="b s" id="lCampos" title="Columnas propias: grupo de laboratorio, subgrupo, tema…">⚙ Campos</button>${CF.length?`<label class="small" style="margin:0">Agrupar por <select id="lAgr"><option value="">—</option>${CF.map(f=>`<option value="${esc(f.id)}" ${CUR.agr===f.id?"selected":""}>${esc(f.nombre)}</option>`).join("")}</select></label>`:""}<button class="b s" id="lExp">📤 Exportar</button></div>${CF.length?'<p class="small muted">Escribe directo en las columnas de tus campos (se guarda al salir de la casilla).</p>':""}
   ${L.length?`<div class="tw"><table class="tabla-c"><tr><th>N°</th><th>Apellidos</th><th>Nombres</th>${CF.map(f=>`<th>${esc(f.nombre)}</th>`).join("")}<th>Documento</th><th>Plan</th><th>Correo</th><th class="n">Asist.</th><th class="n">Nota</th></tr>
   ${L.map(({i,e},k)=>{const a=asisDe(c.id,e.id),n=calcNotas(c.id,e.id);const g=agr?valCF(i,agr):null,gp=agr&&k>0?valCF(L[k-1].i,agr):undefined;const cab=agr&&g!==gp?`<tr class="lgrp"><td colspan="${8+CF.length}"><b>${esc(agr.nombre)}: ${esc(g||"(sin asignar)")}</b> <span class="small muted">${L.filter(x=>valCF(x.i,agr)===g).length}</span></td></tr>`:"";return cab+`<tr class="${i.estado==="retirado"?"ret":""}"><td>${esc(i.n)}</td><td><a href="#" data-est="${esc(e.id)}">${esc(e.ape)}</a></td><td><a href="#" data-est="${esc(e.id)}">${esc(e.nom)}</a>${e.com||i.com?' <span title="Tiene comentarios">💬</span>':""}${i.estado==="retirado"?' <span class="chip">retirado</span>':""}</td>${CF.map(f=>`<td class="cextra"><input class="lCF" data-ins="${esc(i.id)}" data-cf="${esc(f.id)}" value="${esc(valCF(i,f))}" list="lCFL_${esc(f.id)}" aria-label="${esc(f.nombre)}"></td>`).join("")}<td>${esc(e.doc)}</td><td class="small">${esc(e.plan)}</td><td class="small">${esc(e.correo)}</td><td class="n">${a.pct==null?"":a.pct+"%"}</td><td class="n ${n&&n.acum!=null&&n.acum<c.escala.aprueba?"neg":""}">${n&&n.acum!=null?n.acum.toFixed(c.escala.dec):""}</td></tr>`}).join("")}</table></div>${CF.map(f=>`<datalist id="lCFL_${esc(f.id)}">${[...new Set(C.ins.filter(x=>x.cur===c.id).map(x=>valCF(x,f)).filter(Boolean))].slice(0,60).map(v=>`<option value="${esc(v)}">`).join("")}</datalist>`).join("")}`
   :'<div class="card"><p>Aún no hay estudiantes. Usa «Importar listado»: pega lo que copias del SIA o elige el Excel o CSV.</p></div>'}`}
