// ---------- festivos de Colombia (Ley 51 de 1983)
function pascua(y){const a=y%19,b=Math.floor(y/100),c=y%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),mes=Math.floor((h+l-7*m+114)/31),dia=((h+l-7*m+114)%31)+1;return`${y}-${String(mes).padStart(2,"0")}-${String(dia).padStart(2,"0")}`}
const FEST_C={};function festivosCO(y){if(FEST_C[y])return FEST_C[y];const lunes=f=>{const d=dDe(f).getDay();return d===1?f:masDias(f,(8-d)%7)},p=pascua(y),z=n=>`${y}-${n}`;
  const L=[[z("01-01"),"Año Nuevo"],[z("05-01"),"Día del Trabajo"],[z("07-20"),"Independencia"],[z("08-07"),"Batalla de Boyacá"],[z("12-08"),"Inmaculada Concepción"],[z("12-25"),"Navidad"],
    [lunes(z("01-06")),"Reyes Magos"],[lunes(z("03-19")),"San José"],[lunes(z("06-29")),"San Pedro y San Pablo"],[lunes(z("08-15")),"Asunción"],[lunes(z("10-12")),"Día de la Raza"],[lunes(z("11-01")),"Todos los Santos"],[lunes(z("11-11")),"Independencia de Cartagena"],
    [masDias(p,-3),"Jueves Santo"],[masDias(p,-2),"Viernes Santo"],[lunes(masDias(p,39)),"Ascensión"],[lunes(masDias(p,60)),"Corpus Christi"],[lunes(masDias(p,68)),"Sagrado Corazón"]];return FEST_C[y]=Object.fromEntries(L)}
const festivo=f=>festivosCO(+f.slice(0,4))[f]||"";
// ---------- crear sesiones del semestre o de los módulos
function generarSesiones(c){const sm=C.sem.find(s=>s.id===c.sem)||{},H=structuredClone(c.horario||[]),M=c.porMod?(c.modulos||[]):[];const DN=["","lunes","martes","miércoles","jueves","viernes","sábado","domingo"];
  dlg(`📅 Crear sesiones · ${esc(c.nombre)}`,`${M.length?`<label>Módulos</label>${M.map((m,i)=>`<label class="small" style="display:block"><input type="checkbox" data-gm="${i}" ${m.mio?"checked":""}> ${esc(m.nombre)} · ${esc(m.ini)} → ${esc(m.fin)}${m.mio?" (a mi cargo)":m.docente?" ("+esc(m.docente)+")":""}</label>`).join("")}`
     :`<div class="g2c"><div><label>Desde</label><input type="date" id="gsI" value="${esc(sm.ini||"")}"></div><div><label>Hasta</label><input type="date" id="gsF" value="${esc(sm.fin||"")}"></div></div>${!sm.ini?'<p class="small muted">Tip: si pones fechas al semestre, aquí aparecen solas.</p>':""}`}
   <label>Días y horas de clase</label><div id="gsH"></div><button class="b s" id="gsHA">+ Día</button>
   <label class="small" style="display:block;margin-top:6px"><input type="checkbox" id="gsFe" checked> No crear sesiones en festivos de Colombia</label><label class="small" style="display:block"><input type="checkbox" id="gsGH" ${H.length?"":"checked"}> Guardar estos días como el horario del curso</label>
   <div id="gsP" class="small" style="margin-top:6px"></div>`,[["Cancelar","",cerrar],["Crear","p",()=>crear()]]);$("#dlg").classList.add("ancho");
  const pintaH=()=>{if(!H.length)H.push({dia:1,ini:"07:00",fin:"09:00",lugar:""});$("#gsH").innerHTML=H.map((h,i)=>`<div class="filters" style="margin:2px 0"><select data-gd="${i}">${[1,2,3,4,5,6,7].map(d=>`<option value="${d}" ${h.dia===d?"selected":""}>${DN[d]}</option>`).join("")}</select><input type="time" data-gi="${i}" value="${esc(h.ini)}"><input type="time" data-gf="${i}" value="${esc(h.fin)}"><button class="b s" data-gx="${i}">✕</button></div>`).join("");
    document.querySelectorAll("[data-gx]").forEach(b=>b.onclick=()=>{leer();H.splice(+b.dataset.gx,1);pintaH();prev()});document.querySelectorAll("#gsH select,#gsH input").forEach(x=>x.onchange=()=>{leer();prev()})};
  const leer=()=>H.forEach((h,i)=>{if(!$(`[data-gd="${i}"]`))return;h.dia=+$(`[data-gd="${i}"]`).value;h.ini=$(`[data-gi="${i}"]`).value;h.fin=$(`[data-gf="${i}"]`).value});
  const rangos=()=>M.length?M.filter((m,i)=>$(`[data-gm="${i}"]`)&&$(`[data-gm="${i}"]`).checked).map(m=>({ini:m.ini,fin:m.fin,mod:m.id})):[{ini:$("#gsI").value,fin:$("#gsF").value,mod:""}];
  const plan=()=>{leer();const ya=new Set(sesDe(c.id).map(s=>s.fecha+"|"+s.hora)),out=[],fes=[];for(const r of rangos()){if(!r.ini||!r.fin||r.fin<r.ini)continue;for(let f=r.ini;f<=r.fin;f=masDias(f,1)){const dia=((dDe(f).getDay()+6)%7)+1;for(const h of H.filter(x=>x.dia===dia&&x.ini)){if($("#gsFe").checked&&festivo(f)){fes.push(f+" "+festivo(f));continue}if(!ya.has(f+"|"+h.ini))out.push({f,h,mod:r.mod})}}}return{out,fes}};
  const prev=()=>{const {out,fes}=plan(),R=rangos();$("#gsP").innerHTML=!R.some(r=>r.ini&&r.fin)?'<span class="neg">Indica desde y hasta (o marca un módulo).</span>':!H.some(h=>h.ini)?'<span class="neg">Agrega al menos un día con hora.</span>':`Se crearán <b>${out.length}</b> sesiones${out.length?`: ${esc(fechaCorta(out[0].f))} … ${esc(fechaCorta(out[out.length-1].f))}`:""}.${fes.length?` Se omiten ${fes.length} festivos (${esc(fes.slice(0,4).join(", "))}${fes.length>4?"…":""}).`:""}`};
  const crear=()=>{const {out}=plan();if(!out.length){prev();alert("No hay sesiones nuevas para crear con esas fechas y días.");return}for(const {f,h,mod} of out)ponLista("ses",{id:uid(),cur:c.id,mod,fecha:f,hora:h.ini,horaFin:h.fin,tema:"",hecho:"",plan:"",cancelada:false,adjuntos:[]});
    if($("#gsGH").checked)ponLista("cur",{...C.cur.find(x=>x.id===c.id),horario:H.filter(h=>h.ini)});cerrar();aviso(`📅 ${out.length} sesiones creadas`);render()};
  $("#gsHA").onclick=()=>{leer();H.push({dia:(H[H.length-1]||{dia:0}).dia%7+1,ini:"07:00",fin:"09:00",lugar:""});pintaH();prev()};
  ["gsI","gsF","gsFe"].forEach(k=>{const x=$("#"+k);if(x)x.onchange=prev});document.querySelectorAll("[data-gm]").forEach(x=>x.onchange=prev);pintaH();prev()}
// ---------- calendario de cursos (uno o todos)
function vCalCur(L){const f0=CUR.calMes||hoyISO().slice(0,7)+"-01",d=dDe(f0),y=d.getFullYear(),m=d.getMonth(),ini=lunesDe(f0),ids=new Set(L.map(c=>c.id)),S0=C.ses.filter(s=>ids.has(s.cur)),cols=C.col.filter(x=>ids.has(x.cur)&&x.fecha);
  const sems=C.sem.filter(s=>L.some(c=>c.sem===s.id));let h=`<div class="dnav"><button class="b s" id="ccP">◀</button><button class="b s" id="ccH">Hoy</button><h2 class="dtit">${MESL[m]} ${y}</h2><button class="b s" id="ccN">▶</button></div>
   ${L.length>1?`<div class="small" style="margin:4px 0">${L.map(c=>`<span class="chip" style="border-left:4px solid ${c.color||colorCur(c)}">${esc(c.nombre.slice(0,30))}${c.grupo?" G"+esc(c.grupo):""}</span>`).join(" ")}</div>`:""}<div class="mes calcur">${["lun","mar","mié","jue","vie","sáb","dom"].map(x=>`<div class="mh">${x}</div>`).join("")}`;
  for(let i=0;i<42;i++){const f=masDias(ini,i),dd=dDe(f),fe=festivo(f),ss=S0.filter(s=>s.fecha===f).sort((a,b)=>a.hora.localeCompare(b.hora)),cc=cols.filter(x=>x.fecha===f);
    const mods=L.flatMap(c=>(c.porMod?c.modulos:[]).filter(mo=>mo.ini<=f&&mo.fin>=f).map(mo=>({c,mo})));const cortes=sems.flatMap(s=>s.cortes.filter(x=>x.fin===f));const enSem=sems.some(s=>s.ini&&s.fin&&s.ini<=f&&s.fin>=f);
    h+=`<div class="md ${dd.getMonth()!==m?"fuera":""} ${f===hoyISO()?"hoy":""} ${fe?"fest":""} ${enSem?"":"fsem"}"><div class="mn">${dd.getDate()}${fe?` <span class="small" title="${esc(fe)}">🇨🇴</span>`:""}</div>
     ${mods.map(({c,mo})=>`<div class="cmod ${mo.mio?"mio":""}" style="--fc:${c.color||colorCur(c)}" title="${esc(mo.nombre)}${mo.mio?" · a mi cargo":mo.docente?" · "+esc(mo.docente):""}">${f===mo.ini||dd.getDay()===1?esc(mo.nombre.slice(0,18)):"&nbsp;"}</div>`).join("")}
     ${ss.map(s=>{const c=C.cur.find(x=>x.id===s.cur);return`<div class="mt click ${s.cancelada?"ret":""}" data-sesv="${esc(s.id)}" style="border-left:3px solid ${c.color||colorCur(c)}">${esc(s.hora)} ${L.length>1?esc(c.nombre.slice(0,14)):esc((s.tema||"clase").slice(0,18))}</div>`}).join("")}
     ${cc.map(x=>`<div class="mt" style="border-left:3px solid #D85A30">📝 ${esc(x.titulo.slice(0,16))}</div>`).join("")}${cortes.map(x=>`<div class="mt" style="border-left:3px solid #7F77DD">🏁 ${esc(x.n.slice(0,16))}</div>`).join("")}</div>`}
  return h+`</div><p class="small muted">🇨🇴 festivo · 🏁 cierre de corte · 📝 calificación · los días fuera del semestre se ven atenuados. Toca una clase para su bitácora.</p>`}
const colorCur=c=>PAL_FR[[...String(c.id)].reduce((a,x)=>a+x.charCodeAt(0),0)%PAL_FR.length];
function bindCalCur(){const f0=CUR.calMes||hoyISO().slice(0,7)+"-01";const mv=n=>{const d=dDe(f0);d.setMonth(d.getMonth()+n);CUR.calMes=fISO(d).slice(0,8)+"01";render()};$("#ccP").onclick=()=>mv(-1);$("#ccN").onclick=()=>mv(1);$("#ccH").onclick=()=>{CUR.calMes="";render()};document.querySelectorAll("[data-sesv]").forEach(d=>d.onclick=()=>editarSesion(d.dataset.sesv))}
