function vEstudiante(){const e=C.est.find(x=>x.id===CUR.est);if(!e)return'<div class="card">No encontrado</div>';const I=C.ins.filter(i=>i.est===e.id).map(i=>({i,c:C.cur.find(c=>c.id===i.cur)})).filter(x=>x.c);const B=C.bit.filter(b=>b.est===e.id).sort((a,b)=>b.fecha.localeCompare(a.fecha));
  return`<div class="filters"><button class="b s" id="eVol">◀ Volver</button><h2 style="margin:0;flex:1">${esc(nomEst(e))}</h2><button class="b s" id="eEd">✏️ Editar</button><button class="b s" id="eMail" ${e.correo?"":"disabled"}>✉️ Enviar resumen</button></div>
   <div class="card small">${[e.doc&&"🪪 "+esc(e.doc),e.plan&&"🎓 "+esc(e.plan),e.correo&&`✉️ <a href="mailto:${esc(e.correo)}">${esc(e.correo)}</a>`,e.tel&&"📞 "+esc(e.tel)].filter(Boolean).join(" · ")}${e.com?`<div style="margin-top:4px">💬 ${esc(e.com)}</div>`:""}</div>
   ${I.map(({i,c})=>{const R=calcNotas(c.id,e.id),A=asisDe(c.id,e.id),E=c.escala;return`<div class="card"><div class="ih"><b>${esc(c.nombre)}</b> <span class="small muted">${esc((C.sem.find(s=>s.id===c.sem)||{}).nombre||"")} · N° ${esc(i.n)}</span>${i.estado==="retirado"?'<span class="chip">retirado</span>':""}<span class="sp"></span><b class="${R.acum!=null&&R.acum<E.aprueba?"neg":"pos"}">${R.acum==null?"—":R.acum.toFixed(E.dec)}</b></div>
     <div class="small">✋ Asistencia: ${A.tot?`${A.pct}% (${A.P} P, ${A.T} T, ${A.A} A${A.E?`, ${A.E} E`:""})`:"sin registros"}${A.L.filter(x=>x.v==="A").length?` · faltó: ${A.L.filter(x=>x.v==="A").map(x=>esc(fechaCorta(x.s.fecha))).join(", ")}`:""}</div>
     <div class="tw"><table class="tabla-c"><tr><th>Calificación</th><th>Grupo</th><th>Fecha</th><th class="n">Nota</th><th>Comentario</th></tr>${colsDe(c.id).map(x=>{const cel=C.nota[x.id+"|"+e.id]||{};const g=C.grp.find(y=>y.id===x.grp);return`<tr><td>${esc(x.titulo)}</td><td class="small">${esc(g?g.nombre:"")}</td><td class="small">${esc(x.fecha)}</td><td class="n">${esc(cel.v||"")}${x.max!==E.max&&cel.v?`<span class="small muted">/${x.max}</span>`:""}</td><td><input class="ncom" data-ncm="${esc(x.id)}|${esc(e.id)}" value="${esc(cel.c||"")}" placeholder="—"></td></tr>`}).join("")}</table></div>
     <div class="small">${R.grupos.map(x=>`${esc(x.g.nombre)} (${x.g.peso}%): <b>${x.prom==null?"—":redondea(x.prom,2).toFixed(2)}</b>`).join(" · ")}${R.grupos.length?` · Si terminara hoy: <b>${R.defin==null?"—":R.defin.toFixed(E.dec)}</b>`:""}</div></div>`}).join("")}
   <div class="card"><h2>📓 Bitácora</h2><div class="caprow"><input id="bitT" placeholder="Anotación sobre ${esc(e.nom||"el estudiante")}…"><button class="b s p" id="bitG">Agregar</button></div>${B.map(b=>`<div class="small vrow"><span class="muted">${esc(fechaCorta(b.fecha))}</span><span style="flex:1">${esc(b.texto)}</span><button class="b s" data-bitx="${esc(b.id)}">✕</button></div>`).join("")}</div>`}
