// ---------------------------------------------------------------- exportar (Excel, CSV, TXT, PDF)
function tablasCurso(c,que){const L=insDe(c.id,que==="lista"&&CUR.verRet),G=grpDe(c.id),cols=colsDe(c.id),S0=sesDe(c.id).filter(s=>!s.cancelada),E=c.escala;
  if(que==="lista"){const CF=camposC(c);return[["N°","Apellidos","Nombres","Documento","Plan","Correo",...CF.map(f=>f.nombre),"Estado","Asistencia %","Nota acumulada","Comentarios"],...L.map(({i,e})=>{const a=asisDe(c.id,e.id),n=calcNotas(c.id,e.id);return[i.n,e.ape,e.nom,e.doc,e.plan,e.correo,...CF.map(f=>valCF(i,f)),i.estado,a.pct??"",n.acum??"",e.com]})]}
  if(que==="asis")return[["N°","Estudiante",...S0.map(s=>s.fecha+(s.hora?" "+s.hora:"")),"P","T","A","E","%"],...L.map(({i,e})=>{const a=asisDe(c.id,e.id);return[i.n,nomEst(e),...S0.map(s=>(C.asis[s.id+"|"+e.id]||{}).v||""),a.P,a.T,a.A,a.E,a.pct??""]})];
  return[["N°","Estudiante","Documento",...cols.map(x=>x.titulo),...G.map(g=>g.nombre+" ("+g.peso+"%)"),...(c.asisPeso?["Asistencia ("+c.asisPeso+"%)"]:[]),"Acumulada","Si terminara hoy"],...L.map(({i,e})=>{const R=calcNotas(c.id,e.id);return[i.n,nomEst(e),e.doc,...cols.map(x=>{const n=numNota((C.nota[x.id+"|"+e.id]||{}).v);return n??""}),...R.grupos.map(x=>x.prom==null?"":redondea(x.prom,2)),R.acum??"",R.defin??""]})]}
function exportarCurso(c,que){const nom={lista:"Listado",asis:"Asistencia",notas:"Notas"}[que],base=`${c.nombre} ${c.grupo?"G"+c.grupo:""} ${nom}`.replace(/[^\w\sáéíóúñÁÉÍÓÚÑ-]/g,"").replace(/\s+/g,"_");
  dlg(`📤 Exportar ${nom.toLowerCase()}`,`<div class="filters" style="flex-direction:column;align-items:stretch">${[["xlsx","📗 Excel (.xlsx) — lista, asistencia y notas en hojas"],["csv","CSV (para Sheets, Excel o el script de correo)"],["txt","Texto separado por tabulaciones"],["pdf","🖨️ PDF (imprimir)"]].map(([k,l])=>`<button class="b" data-ex="${k}">${l}</button>`).join("")}</div>`,[["Cerrar","",cerrar]]);
  document.querySelectorAll("[data-ex]").forEach(b=>b.onclick=async()=>{const f=b.dataset.ex,T=tablasCurso(c,que);cerrar();
    if(f==="xlsx"){try{const H=["lista","asis","notas"].map(q=>({nombre:{lista:"Listado",asis:"Asistencia",notas:"Notas"}[q],filas:tablasCurso(c,q),anchos:q==="lista"?[6,22,22,14,24,28,10,10,10,30]:null}));descargar(await escribirExcel(H),base+".xlsx")}catch(e){alert(e.message)}}
    else if(f==="csv"){const q=v=>`"${String(v??"").replace(/"/g,'""')}"`;descargar(new Blob(["\ufeff"+T.map(r=>r.map(q).join(";")).join("\n")],{type:"text/csv"}),base+".csv")}
    else if(f==="txt")descargar(new Blob([T.map(r=>r.join("\t")).join("\n")],{type:"text/plain"}),base+".txt");
    else imprimirTabla(`${c.nombre}${c.grupo?" · grupo "+c.grupo:""} — ${nom}`,`${(C.sem.find(s=>s.id===c.sem)||{}).nombre||""} · ${c.codoc?"Docentes: "+c.codoc+" · ":""}generado ${fechaLarga(hoyISO())}`,T)})}
function imprimirTabla(tit,sub,T){const w=window.open("","_blank");if(!w){alert("Permite las ventanas emergentes para imprimir");return}
  w.document.write(`<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><title>${esc(tit)}</title><style>body{font:11px/1.35 Arial,sans-serif;margin:16px;color:#111}h1{font-size:15px;margin:0}p{margin:2px 0 10px;color:#555}table{border-collapse:collapse;width:100%}th,td{border:1px solid #999;padding:3px 5px;text-align:left}th{background:#eee}tr:nth-child(even) td{background:#fafafa}@page{size:${T[0].length>10?"landscape":"portrait"};margin:12mm}</style></head><body><h1>${esc(tit)}</h1><p>${esc(sub)}</p><table>${T.map((r,i)=>`<tr>${r.map(v=>i?`<td>${esc(v)}</td>`:`<th>${esc(v)}</th>`).join("")}</tr>`).join("")}</table></body></html>`);w.document.close();setTimeout(()=>{w.focus();w.print()},300)}
